            int ci = 2 * cp + e; float w = ci < CI ? Wt[t * CI * CO + ci * CO + co] : 0.0f;
            nsq_w[L][((t * (CIp / 2) + cp) * CO + co) * 2 + e] = (int16_t)lrintf(w * sc);
